-- mod-hearthstone: opponent deck library and the opponent registry.
-- GENERATED by tools/decks/gen_deck_library.py from data/decks/base_decks.json and
-- data/decks/source/deck_archive_2014.md. Do not edit by hand: change an input and regenerate.
--
-- hearthstone_deck_template is the module-owned library of prepared decks. This file rebuilds
-- it in full (DROP + CREATE + INSERT), so the changed file has a new SHA1 and the core AutoUpdater
-- runs it again at the next startup. Do not add your own decks there, they would be lost. Owner decks
-- that the module should not touch go to hearthstone_opponent and use the deck keys below.
--
-- cards is a list of card id and copies: ID:COUNT,ID:COUNT,... for exactly 30 cards. Every deck is
-- checked at server startup: known cards that the match engine supports, the deck class or NEUTRAL
-- cards only, at most 2 copies of a card and 1 of a Legendary. A deck that fails is skipped and the
-- reason is logged (see .hs match decks).
--
-- kind: opponent (the module decks normal_<class> and hard_<class>), starter (the nine launch-era
-- Basic decks, starter_<class>, awarded with a class), npc (the decks of the quest-unlocked NPCs,
-- npc_<name>) and library (the 2014 class library, lib_<class>_<entry>). finder: the pool of the
-- match-finder the deck joins (normal = rated Easy, hard = rated Hard, none = not in the finder).
-- ladder_easy and ladder_hard are decks for the NPC ladder only: rated Easy or Hard, not in the match-finder.
-- Provenance of every deck: data/decks/deck_library.json.
--
-- hearthstone_opponent is owner data: CREATE TABLE IF NOT EXISTS, never dropped, no rows seeded.
-- One row names a creature entry, a difficulty and a library deck. Several rows with the same entry
-- and difficulty form a pool and the match picks one of them at random. difficulty boss gives no
-- difficulty choice and always plays the Hard AI. hero_health NULL = 30, hero_armor NULL = 0,
-- hero_power NULL = the class hero power, hero_card NULL = the class hero. The README of the module
-- has examples.
--
-- The file contains no backslashes (the updater guesses string state from the previous character),
-- no semicolons and no apostrophes inside comments or strings: keep it that way.

DROP TABLE IF EXISTS `hearthstone_deck_template`;

CREATE TABLE `hearthstone_deck_template` (
  `deck_key` VARCHAR(32) NOT NULL,
  `name` VARCHAR(64) NOT NULL,
  `deck_class` VARCHAR(16) NOT NULL,
  `kind` ENUM('opponent','starter','npc','library') NOT NULL DEFAULT 'opponent',
  `finder` ENUM('none','normal','hard','ladder_easy','ladder_hard') NOT NULL DEFAULT 'none',
  `cards` VARCHAR(1024) NOT NULL,
  PRIMARY KEY (`deck_key`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='Prepared decks of mod-hearthstone (rebuilt by the module migration)';


-- hearthstone_npc_unlock is module data like the library (rebuilt in full): the quest NPCs. A
-- creature listed here offers Play a game of Hearthstone (Normal and Hard, its npc deck) only to accounts
-- that unlocked it: any character of the account turned in quest_id. faction is the side of the NPC
-- (alliance or horde): an unlocked NPC also joins the match-finder pool of characters of that side.
-- Sources: data/decks/npc_unlocks.json and data/quests/class_unlocks.json.
-- Class quest NPCs have quest-only direct duels, then join the account random roster.

DROP TABLE IF EXISTS `hearthstone_npc_unlock`;

CREATE TABLE `hearthstone_npc_unlock` (
  `creature_entry` INT UNSIGNED NOT NULL,
  `quest_id` INT UNSIGNED NOT NULL,
  `deck_key` VARCHAR(32) NOT NULL,
  `faction` ENUM('alliance','horde') NOT NULL,
  PRIMARY KEY (`creature_entry`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='Quest-unlocked NPC opponents of mod-hearthstone (rebuilt by the module migration)';


CREATE TABLE IF NOT EXISTS `hearthstone_opponent` (
  `creature_entry` INT UNSIGNED NOT NULL,
  `difficulty` ENUM('normal','hard','boss') NOT NULL,
  `deck_key` VARCHAR(32) NOT NULL,
  `hero_health` SMALLINT UNSIGNED NULL,
  `hero_power` VARCHAR(32) NULL,
  `hero_card` VARCHAR(32) NULL,
  `hero_armor` SMALLINT UNSIGNED NULL,
  PRIMARY KEY (`creature_entry`, `difficulty`, `deck_key`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='Match opponents of mod-hearthstone (owner data, never dropped by the module)';
